     1→/**
     2→ * FreeWire — AI Graph Generator
     3→ *
     4→ * Claude API → 노드 그래프 JSON 동적 생성
     5→ *
     6→ * 사용자의 자연어 설명을 받아서
     7→ * FreeWire 노드 + 와이어 구조를 생성한다.
     8→ *
     9→ * API 키가 없으면 AINodeGenerator(규칙 기반) 폴백으로 동작한다.
    10→ */
    11→
    12→'use strict';
    13→
    14→let Anthropic;
    15→try {
    16→  Anthropic = require('@anthropic-ai/sdk');
    17→} catch (_) {
    18→  Anthropic = null;
    19→}
    20→
    21→const { AINodeGenerator } = require('../ai/node-generator');
    22→
    23→// ─── 노드 타입 레퍼런스 (Claude에게 알려줄 스펙) ─────────────────
    24→
    25→const NODE_SPEC = `
    26→# FreeWire 노드 스펙
    27→
    28→## 노드 타입
    29→
    30→### component 노드 (UI 요소)
    31→- button:    { type:"component", subtype:"button",    props:{label:"텍스트", variant:"primary|secondary|ghost|danger"} }
    32→- text:      { type:"component", subtype:"text",      props:{content:"텍스트", tag:"h1|h2|h3|p|span|label"} }
    33→- input:     { type:"component", subtype:"input",     props:{placeholder:"힌트", type:"text|email|password|number"} }
    34→- card:      { type:"component", subtype:"card",      props:{title:"제목"} }
    35→- container: { type:"component", subtype:"container", props:{direction:"row|column", gap:"8px"} }
    36→- image:     { type:"component", subtype:"image",     props:{src:"url", alt:"설명"} }
    37→- badge:     { type:"component", subtype:"badge",     props:{text:"배지", color:"blue|green|red|yellow"} }
    38→
    39→### data 노드 (데이터 흐름)
    40→- state:     { type:"data", subtype:"state",   props:{name:"변수명", initial:"초기값"} }
    41→- const:     { type:"data", subtype:"const",   props:{value:"값", valueType:"string|number|boolean"} }
    42→- array:     { type:"data", subtype:"array",   props:{items:"[]"} }
    43→- props:     { type:"data", subtype:"props",   props:{schema:"{}"} }
    44→
    45→### logic 노드 (제어 흐름)
    46→- handler:   { type:"logic", subtype:"handler",   props:{name:"함수명"} }
    47→- setState:  { type:"logic", subtype:"setState",  props:{stateName:"변수명", value:"새값"} }
    48→- ifelse:    { type:"logic", subtype:"ifelse",    props:{condition:"조건식"} }
    49→
    50→## 와이어 구조
    51→{ from: "노드ID", fromPort: 0, to: "노드ID", toPort: 0 }
    52→
    53→## 포트 컨벤션
    54→- button  inputs[0]=props, inputs[1]=onClick(핸들러 연결)
    55→- text    inputs[0]=content(데이터 바인딩)
    56→- input   inputs[0]=value, inputs[1]=onChange
    57→- card    inputs[0..n]=children
    58→- container inputs[0..n]=children
    59→- handler → button: { from:handlerId, fromPort:0, to:buttonId, toPort:1 }
    60→- state   → text:   { from:stateId,   fromPort:0, to:textId,   toPort:0 }
    61→`;
    62→
    63→const SYSTEM_PROMPT = `당신은 FreeWire 노드 그래프 생성기입니다.
    64→사용자의 UI 설명을 읽고 FreeWire 노드 그래프 JSON을 생성합니다.
    65→
    66→${NODE_SPEC}
    67→
    68→## 응답 형식 (반드시 순수 JSON만 반환, 설명 텍스트 없이)
    69→
    70→{
    71→  "label": "그래프 이름",
    72→  "nodes": [
    73→    { "id": "n1", "type": "component", "subtype": "button", "label": "버튼[로그인]", "props": {"label":"로그인","variant":"primary"} },
    74→    ...
    75→  ],
    76→  "edges": [
    77→    { "id": "e1", "from": "n2", "fromPort": 0, "to": "n1", "toPort": 1 },
    78→    ...
    79→  ]
    80→}
    81→
    82→## 규칙
    83→1. 노드 ID는 "n1", "n2" 형식
    84→2. 와이어 ID는 "e1", "e2" 형식
    85→3. 버튼이 있으면 반드시 handler 노드와 연결 (toPort: 1)
    86→4. state 노드가 있으면 반드시 text 노드에 바인딩 (fromPort:0, toPort:0)
    87→5. 관련 노드들은 card나 container로 묶기
    88→6. label은 "타입[이름]" 형식 (예: "버튼[로그인]", "상태[count]")
    89→7. 사용자 요청을 정확히 반영 — 없다고 한 것은 만들지 않기
    90→8. 순수 JSON만 반환 (코드블록, 설명 없음)`;
    91→
    92→// ─── 메인 함수 ──────────────────────────────────────────────────
    93→
    94→/**
    95→ * 자연어 프롬프트 → FreeWire 그래프 JSON 생성
    96→ *
    97→ * @param {string} prompt   - 자연어 UI 설명
    98→ * @param {string} [apiKey] - Claude API 키 (없으면 규칙 기반 폴백)
    99→ * @returns {Promise<object>} { graph, label, nodeCount, edgeCount, source, rawPrompt }
   100→ */
   101→async function aiGenerateGraph(prompt, apiKey) {
   102→  // ── 입력 검증 ────────────────────────────────────────────────
   103→  if (!prompt || typeof prompt !== 'string') {
   104→    throw new Error('prompt는 비어 있지 않은 문자열이어야 합니다');
   105→  }
   106→  const trimmed = prompt.trim();
   107→  if (trimmed.length === 0) {
   108→    throw new Error('prompt는 비어 있지 않은 문자열이어야 합니다');
   109→  }
   110→  if (trimmed.length > 2000) {
   111→    throw new Error('prompt가 너무 깁니다 (최대 2000자)');
   112→  }
   113→
   114→  const key = apiKey || process.env.ANTHROPIC_API_KEY;
   115→
   116→  // ── API 키 없음 → 규칙 기반 폴백 ─────────────────────────────
   117→  if (!key || !Anthropic) {
   118→    return _fallbackGenerate(trimmed);
   119→  }
   120→
   121→  // ── Claude API 호출 ───────────────────────────────────────────
   122→  try {
   123→    const client = new Anthropic({ apiKey: key });
   124→
   125→    const message = await client.messages.create({
   126→      model: 'claude-haiku-4-5-20251001',
   127→      max_tokens: 2048,
   128→      system: SYSTEM_PROMPT,
   129→      messages: [{ role: 'user', content: trimmed }],
   130→    });
   131→
   132→    const raw = message.content[0]?.text ?? '';
   133→    const graph = parseGraphJSON(raw);
   134→
   135→    // 레이아웃 계산
   136→    graph.nodes = applyLayout(graph.nodes);
   137→
   138→    return {
   139→      graph,
   140→      label:     graph.label,
   141→      nodeCount: graph.nodes.length,
   142→      edgeCount: graph.edges.length,
   143→      source:    'claude-api',
   144→      model:     message.model,
   145→      usage:     message.usage,
   146→      rawPrompt: trimmed,
   147→    };
   148→  } catch (e) {
   149→    // API 실패 시 규칙 기반 폴백
   150→    if (e.message && e.message.includes('API 키')) throw e;  // 인증 오류는 재전파
   151→    const fallback = await _fallbackGenerate(trimmed);
   152→    fallback.fallbackReason = e.message;
   153→    return fallback;
   154→  }
   155→}
   156→
   157→// ─── 규칙 기반 폴백 ─────────────────────────────────────────────
   158→
   159→async function _fallbackGenerate(prompt) {
   160→  const generator = new AINodeGenerator();
   161→  const result = await generator.generate(prompt);
   162→
   163→  // nodes 객체 → 배열로 변환 (parseGraphJSON 포맷과 통일)
   164→  const nodesArray = Object.values(result.nodes ?? {});
   165→  const edgesArray = (result.edges ?? []).map((e, i) => ({
   166→    id:       e.id ?? `e${i + 1}`,
   167→    from:     e.fn ?? e.from,
   168→    fromPort: e.fp ?? e.fromPort ?? 0,
   169→    to:       e.tn ?? e.to,
   170→    toPort:   e.tp ?? e.toPort ?? 0,
   171→  }));
   172→
   173→  // 레이아웃 적용
   174→  const nodesWithLayout = applyLayout(nodesArray);
   175→
   176→  const graph = {
   177→    label: result.label ?? 'AI 생성 그래프',
   178→    nodes: nodesWithLayout,
   179→    edges: edgesArray,
   180→  };
   181→
   182→  return {
   183→    graph,
   184→    label:     graph.label,
   185→    nodeCount: nodesWithLayout.length,
   186→    edgeCount: edgesArray.length,
   187→    source:    'rule-based-fallback',
   188→    intent:    result.intent,
   189→    rawPrompt: prompt,
   190→  };
   191→}
   192→
   193→// ─── JSON 파싱 (방어적) ─────────────────────────────────────────
   194→
   195→function parseGraphJSON(raw) {
   196→  // 코드블록 제거
   197→  let text = raw.trim()
   198→    .replace(/^```json\s*/i, '')
   199→    .replace(/^```\s*/i, '')
   200→    .replace(/\s*```$/, '')
   201→    .trim();
   202→
   203→  // JSON 시작 위치 찾기
   204→  const start = text.indexOf('{');
   205→  const end   = text.lastIndexOf('}');
   206→  if (start === -1 || end === -1) throw new Error('JSON 응답을 찾을 수 없습니다');
   207→
   208→  text = text.slice(start, end + 1);
   209→
   210→  let graph;
   211→  try {
   212→    graph = JSON.parse(text);
   213→  } catch (e) {
   214→    console.error('[AI] JSON 파싱 실패. 원본(200자):', text.slice(0, 200));
   215→    throw new Error('Claude API 응답을 JSON으로 파싱하지 못했습니다: ' + e.message);
   216→  }
   217→
   218→  // 필수 필드 보장
   219→  if (!graph.nodes) graph.nodes = [];
   220→  if (!graph.edges) graph.edges = [];
   221→  if (!graph.label) graph.label = 'AI 생성 그래프';
   222→
   223→  // edge id 보장
   224→  graph.edges = graph.edges.map((e, i) => ({
   225→    id: e.id ?? `e${i + 1}`,
   226→    from:      e.from      ?? e.fromNode,
   227→    fromPort:  e.fromPort  ?? 0,
   228→    to:        e.to        ?? e.toNode,
   229→    toPort:    e.toPort    ?? 0,
   230→  }));
   231→
   232→  return graph;
   233→}
   234→
   235→// ─── 자동 레이아웃 ──────────────────────────────────────────────
   236→
   237→function applyLayout(nodes) {
   238→  const W = 200, H = 130, GAP_X = 70, GAP_Y = 24;
   239→
   240→  // type 순서: data → logic → component
   241→  const ORDER = { data: 0, logic: 1, component: 2 };
   242→  const cols   = { data: [], logic: [], component: [] };
   243→
   244→  for (const n of nodes) {
   245→    const col = cols[n.type] ?? cols.component;
   246→    col.push(n);
   247→  }
   248→
   249→  let x = 80;
   250→  const result = [];
   251→
   252→  for (const [typeName, col] of Object.entries(cols)) {
   253→    if (col.length === 0) continue;
   254→    col.forEach((n, i) => {
   255→      result.push({ ...n, position: { x, y: 80 + i * (H + GAP_Y) } });
   256→    });
   257→    x += W + GAP_X;
   258→  }
   259→
   260→  return result;
   261→}
   262→
   263→module.exports = { aiGenerateGraph };
   264→

