     1→/**
     2→ * FreeWire Phase 7 — Intent Evaluator
     3→ *
     4→ * "버튼이 렌더되나?" 가 아니라
     5→ * "인증이 시작될 수 있는 상태인가?" 를 판단한다.
     6→ *
     7→ * 세 가지를 검사한다:
     8→ *   1. Structural Check  — 필요한 노드/와이어가 존재하는가?
     9→ *   2. Contract Check    — 각 노드의 requires가 충족되는가?
    10→ *   3. Goal Check        — 목표 Facts가 그래프에서 생산 가능한가?
    11→ */
    12→
    13→'use strict';
    14→
    15→const { NODE_INTENT_DEFAULTS, parseGoalToFacts, wireFrom, wireTo } = require('./intent-spec');
    16→
    17→// ─── 위반 구조 ─────────────────────────────────────────────────
    18→
    19→const VALID_SEVERITIES = new Set(['error', 'warning']);
    20→
    21→class ContractViolation {
    22→  constructor({ nodeId, nodeLabel, type, fact, message, severity, repairHint }) {
    23→    this.nodeId    = nodeId;
    24→    this.nodeLabel = nodeLabel;
    25→    this.type      = type;       // 'requires' | 'ensures' | 'goal' | 'structural' | 'warning'
    26→    this.fact      = fact;       // 위반된 fact
    27→    this.message   = message;    // 사람이 읽을 수 있는 설명
    28→    // 유효하지 않은 severity는 'error'로 fallback
    29→    this.severity  = VALID_SEVERITIES.has(severity) ? severity : 'error';
    30→    this.repairHint= repairHint; // 수정 방향 힌트
    31→  }
    32→
    33→  toString() {
    34→    const sev = this.severity ?? 'unknown';
    35→    return `[${sev.toUpperCase()}] ${this.nodeLabel}: ${this.message}`;
    36→  }
    37→}
    38→
    39→// ─── Intent Evaluator ──────────────────────────────────────────
    40→
    41→class IntentEvaluator {
    42→  /**
    43→   * @param {Map}    nodes  - editor.nodes (NodeView Map)
    44→   * @param {Map}    wires  - editor.wires (wire Map)
    45→   * @param {string} goal   - 사용자 원래 의도 ("로그인 폼 만들어줘")
    46→   */
    47→  evaluate(nodes, wires, goal = '') {
    48→    if (!nodes || typeof nodes.values !== 'function') nodes = new Map();
    49→    if (!wires || typeof wires.values !== 'function') wires = new Map();
    50→    const nodesArr = this._extractDefs(nodes);
    51→    const wiresArr = [...wires.values()];
    52→
    53→    const violations = [];
    54→    const satisfiedFacts = new Set();
    55→
    56→    // 1) 구조 검사: 빈 그래프
    57→    if (nodesArr.length === 0) {
    58→      violations.push(new ContractViolation({
    59→        nodeId: null, nodeLabel: '그래프',
    60→        type: 'structural', fact: 'graph.nonempty',
    61→        message: '노드가 없습니다. UI를 만들려면 노드를 추가하세요.',
    62→        severity: 'error', repairHint: 'add_node',
    63→      }));
    64→      return this._buildReport(violations, satisfiedFacts, goal, nodesArr, wiresArr);
    65→    }
    66→
    67→    // 2) 각 노드의 Contract 검사
    68→    for (const node of nodesArr) {
    69→      const contract = node.contract ?? this._getDefaultContract(node.subtype);
    70→      const producedByConnected = this._factsProducedByInputs(node, nodesArr, wiresArr);
    71→
    72→      // requires 검사
    73→      for (const req of (contract.requires ?? [])) {
    74→        if (!producedByConnected.has(req) && !satisfiedFacts.has(req)) {
    75→          violations.push(new ContractViolation({
    76→            nodeId: node.id, nodeLabel: node.label ?? node.subtype,
    77→            type: 'requires', fact: req,
    78→            message: `"${req}" 조건이 필요하지만 연결된 노드가 제공하지 않습니다.`,
    79→            severity: 'error',
    80→            repairHint: `connect_${req.split('.')[0]}`,
    81→          }));
    82→        }
    83→      }
    84→
    85→      // warns 검사 (권장)
    86→      for (const warn of (contract.warns ?? [])) {
    87→        if (!producedByConnected.has(warn)) {
    88→          violations.push(new ContractViolation({
    89→            nodeId: node.id, nodeLabel: node.label ?? node.subtype,
    90→            type: 'warning', fact: warn,
    91→            message: `"${warn}" 조건이 충족되면 더 완전한 UI가 됩니다.`,
    92→            severity: 'warning',
    93→            repairHint: `enhance_${warn.split('.')[0]}`,
    94→          }));
    95→        }
    96→      }
    97→
    98→      // 이 노드가 produces하는 facts 수집
    99→      for (const p of (contract.produces ?? [])) satisfiedFacts.add(p);
   100→      for (const e of (contract.ensures ?? []))  satisfiedFacts.add(e);
   101→    }
   102→
   103→    // 3) 특수 구조 검사
   104→    this._checkButtonHandlerConnections(nodesArr, wiresArr, violations);
   105→    this._checkStateBindings(nodesArr, wiresArr, violations, satisfiedFacts);
   106→    this._checkOrphanNodes(nodesArr, wiresArr, violations);
   107→
   108→    // 4) Goal Facts 검사
   109→    if (goal) {
   110→      const goalFacts = parseGoalToFacts(goal);
   111→      for (const gf of goalFacts) {
   112→        if (!satisfiedFacts.has(gf)) {
   113→          violations.push(new ContractViolation({
   114→            nodeId: null, nodeLabel: '목표',
   115→            type: 'goal', fact: gf,
   116→            message: `목표 달성에 필요한 "${gf}"가 현재 그래프에서 생산되지 않습니다.`,
   117→            severity: 'error',
   118→            repairHint: `goal_${gf.replace(/\./g, '_')}`,
   119→          }));
   120→        }
   121→      }
   122→    }
   123→
   124→    return this._buildReport(violations, satisfiedFacts, goal, nodesArr, wiresArr);
   125→  }
   126→
   127→  // ─── 특수 구조 검사들 ──────────────────────────────────────
   128→
   129→  _checkButtonHandlerConnections(nodesArr, wiresArr, violations) {
   130→    const buttons  = nodesArr.filter(n => n.subtype === 'button');
   131→    const handlers = nodesArr.filter(n => n.subtype === 'handler');
   132→
   133→    for (const btn of buttons) {
   134→      // 버튼의 onClick 포트(인덱스 1)에 핸들러가 연결됐는지 확인
   135→      const connected = wiresArr.some(w =>
   136→        wireTo(w) === btn.id && (w.tp ?? w.toPort ?? w.to?.portId) === 1
   137→      );
   138→      if (!connected && handlers.length > 0) {
   139→        violations.push(new ContractViolation({
   140→          nodeId: btn.id, nodeLabel: btn.label ?? '버튼',
   141→          type: 'structural', fact: 'ui.button.connected',
   142→          message: `버튼 "${btn.props?.label ?? btn.id}"에 클릭 핸들러가 연결되지 않았습니다. 클릭해도 아무 일도 일어나지 않습니다.`,
   143→          severity: 'error',
   144→          repairHint: 'wire_handler_to_button',
   145→        }));
   146→      }
   147→    }
   148→
   149→    // 핸들러가 아예 없는데 버튼은 있는 경우
   150→    if (buttons.length > 0 && handlers.length === 0) {
   151→      violations.push(new ContractViolation({
   152→        nodeId: null, nodeLabel: '그래프',
   153→        type: 'structural', fact: 'action.handler.present',
   154→        message: `버튼이 ${buttons.length}개 있지만 이벤트 핸들러가 없습니다. 버튼 클릭이 동작하지 않습니다.`,
   155→        severity: 'error',
   156→        repairHint: 'add_handler_node',
   157→      }));
   158→    }
   159→  }
   160→
   161→  _checkStateBindings(nodesArr, wiresArr, violations, satisfiedFacts) {
   162→    const stateNodes = nodesArr.filter(n => n.subtype === 'state');
   163→    const textNodes  = nodesArr.filter(n => n.subtype === 'text');
   164→
   165→    for (const st of stateNodes) {
   166→      // state가 text/컴포넌트에 연결됐는지
   167→      const hasOutput = wiresArr.some(w => wireFrom(w) === st.id);
   168→      if (!hasOutput && textNodes.length > 0) {
   169→        violations.push(new ContractViolation({
   170→          nodeId: st.id, nodeLabel: st.label ?? '상태',
   171→          type: 'structural', fact: 'state.bound',
   172→          message: `상태 "${st.props?.name ?? st.id}"가 UI에 바인딩되지 않았습니다. 상태가 변해도 화면이 갱신되지 않습니다.`,
   173→          severity: 'warning',
   174→          repairHint: 'wire_state_to_display',
   175→        }));
   176→      } else if (hasOutput) {
   177→        satisfiedFacts.add('state.bound');
   178→      }
   179→    }
   180→  }
   181→
   182→  _checkOrphanNodes(nodesArr, wiresArr, violations) {
   183→    if (nodesArr.length < 3) return; // 소규모 그래프는 고아 체크 생략
   184→
   185→    for (const node of nodesArr) {
   186→      if (node.type !== 'component') continue;
   187→      const hasAnyWire = wiresArr.some(w =>
   188→        wireFrom(w) === node.id || wireTo(w) === node.id
   189→      );
   190→      if (!hasAnyWire) {
   191→        violations.push(new ContractViolation({
   192→          nodeId: node.id, nodeLabel: node.label ?? node.subtype,
   193→          type: 'structural', fact: 'node.connected',
   194→          message: `노드 "${node.label ?? node.id}"가 다른 노드와 연결되지 않았습니다. 고립된 상태입니다.`,
   195→          severity: 'warning',
   196→          repairHint: 'connect_orphan',
   197→        }));
   198→      }
   199→    }
   200→  }
   201→
   202→  // ─── 헬퍼 ────────────────────────────────────────────────────
   203→
   204→  _extractDefs(nodes) {
   205→    return [...nodes.values()].map(v => v.def ?? v);
   206→  }
   207→
   208→  _getDefaultContract(subtype) {
   209→    return NODE_INTENT_DEFAULTS[subtype]?.contract ?? { requires: [], ensures: [], produces: [], warns: [] };
   210→  }
   211→
   212→  /**
   213→   * 이 노드의 입력 포트에 연결된 노드들이 produces하는 facts
   214→   */
   215→  _factsProducedByInputs(node, nodesArr, wiresArr) {
   216→    const produced = new Set();
   217→    const inputWires = wiresArr.filter(w => wireTo(w) === node.id);
   218→
   219→    for (const wire of inputWires) {
   220→      const sourceNode = nodesArr.find(n => n.id === wireFrom(wire));
   221→      if (!sourceNode) continue;
   222→      const contract = sourceNode.contract ?? this._getDefaultContract(sourceNode.subtype);
   223→      for (const p of (contract.produces ?? [])) produced.add(p);
   224→      for (const e of (contract.ensures  ?? [])) produced.add(e);
   225→    }
   226→
   227→    return produced;
   228→  }
   229→
   230→  _buildReport(violations, satisfiedFacts, goal, nodesArr, wiresArr) {
   231→    const errors   = violations.filter(v => v.severity === 'error');
   232→    const warnings = violations.filter(v => v.severity === 'warning');
   233→
   234→    const totalFacts     = goal ? parseGoalToFacts(goal) : [];
   235→    const satisfiedGoals = totalFacts.filter(f => satisfiedFacts.has(f));
   236→    const score = totalFacts.length > 0
   237→      ? Math.round((satisfiedGoals.length / totalFacts.length) * 100)
   238→      : (errors.length === 0 ? 100 : 0);
   239→
   240→    return {
   241→      score,                    // 0-100 — 의도 충족 점수
   242→      passed: errors.length === 0,
   243→      errors,
   244→      warnings,
   245→      violations,
   246→      satisfiedFacts: [...satisfiedFacts],
   247→      missingFacts: totalFacts.filter(f => !satisfiedFacts.has(f)),
   248→      summary: this._buildSummary(score, errors, warnings, nodesArr, wiresArr),
   249→    };
   250→  }
   251→
   252→  _buildSummary(score, errors, warnings, nodesArr, wiresArr) {
   253→    if (errors.length === 0 && warnings.length === 0) {
   254→      return `✅ 의도 100% 충족 — 모든 계약이 만족됩니다`;
   255→    }
   256→    const parts = [];
   257→    if (score < 100) parts.push(`의도 충족률: ${score}%`);
   258→    if (errors.length)   parts.push(`오류 ${errors.length}개`);
   259→    if (warnings.length) parts.push(`경고 ${warnings.length}개`);
   260→    parts.push(`노드 ${nodesArr.length}개 / 와이어 ${wiresArr.length}개`);
   261→    return parts.join(' | ');
   262→  }
   263→}
   264→
   265→module.exports = { IntentEvaluator, ContractViolation };
   266→

