     1→/**
     2→ * FreeWire - .free 코드 → HTML/CSS/JS 실행기
     3→ * FreeLang Light 컴파일러 로직을 내장하여 의존성 없이 동작
     4→ */
     5→
     6→class FreeExecutor {
     7→  /**
     8→   * @param {string} freeCode  - GraphCompiler가 생성한 .free 문자열
     9→   * @param {object} graphJson - 원본 그래프 JSON (메타 정보 참조용)
    10→   * @returns {{ html: string, css: string, js: string, stats: object }}
    11→   */
    12→  execute(freeCode, graphJson = {}) {
    13→    const sections = this._parseSections(freeCode);
    14→
    15→    const css  = this._compileStyle(sections.style);
    16→    const js   = this._compileScript(sections.script);
    17→    const html = this._compileMarkup(sections.markup);
    18→
    19→    return {
    20→      html,
    21→      css,
    22→      js,
    23→      stats: {
    24→        htmlBytes: html.length,
    25→        cssBytes:  css.length,
    26→        jsBytes:   js.length,
    27→        sections:  Object.keys(sections).filter(k => sections[k]),
    28→      },
    29→    };
    30→  }
    31→
    32→  // ─── 파서: .free 섹션 분리 ──────────────────────────────────
    33→
    34→  _parseSections(code) {
    35→    const sections = { props: '', style: '', script: '', markup: '' };
    36→    const pattern  = /\b(props|style|script|markup)\s*\{/g;
    37→    let match;
    38→    const positions = [];
    39→
    40→    while ((match = pattern.exec(code)) !== null) {
    41→      positions.push({ type: match[1], start: match.index + match[0].length, matchStart: match.index });
    42→    }
    43→
    44→    // 최상위 섹션만 추출 (이미 추출된 블록 범위 안에 있는 것은 스킵)
    45→    const usedRanges = [];
    46→    positions.forEach((pos) => {
    47→      const isNested = usedRanges.some(([s, e]) => pos.matchStart >= s && pos.matchStart < e);
    48→      if (isNested) return;
    49→      const end   = this._findBlockEnd(code, pos.start - 1);
    50→      const inner = code.slice(pos.start, end).trim();
    51→      sections[pos.type] += '\n' + inner;
    52→      usedRanges.push([pos.matchStart, end]);
    53→    });
    54→
    55→    return sections;
    56→  }
    57→
    58→  _findBlockEnd(code, openBrace) {
    59→    // openBrace 위치에서 '{' 찾기
    60→    let idx = openBrace;
    61→    while (idx < code.length && code[idx] !== '{') idx++;
    62→    let depth = 1;
    63→    idx++;
    64→    while (idx < code.length && depth > 0) {
    65→      if (code[idx] === '{') depth++;
    66→      else if (code[idx] === '}') depth--;
    67→      idx++;
    68→    }
    69→    return idx - 1;
    70→  }
    71→
    72→  // ─── CSS 컴파일 ─────────────────────────────────────────────
    73→
    74→  _compileStyle(styleBlock) {
    75→    if (!styleBlock.trim()) return '';
    76→
    77→    // camelCase → kebab-case
    78→    return styleBlock
    79→      .replace(/([a-z])([A-Z])/g, '$1-$2')
    80→      .toLowerCase()
    81→      .replace(/\s*\n\s*/g, '\n')
    82→      .trim();
    83→  }
    84→
    85→  // ─── JS 컴파일 ──────────────────────────────────────────────
    86→
    87→  _compileScript(scriptBlock) {
    88→    if (!scriptBlock.trim()) return '';
    89→
    90→    const lines = scriptBlock.split('\n').map(l => l.trim()).filter(Boolean);
    91→    const output = [];
    92→
    93→    output.push('(function() {');
    94→    output.push('  "use strict";');
    95→    output.push('  var _ctx = {};');
    96→
    97→    lines.forEach(line => {
    98→      // 주석 라인은 그대로
    99→      if (line.startsWith('//')) {
   100→        output.push('  ' + line);
   101→        return;
   102→      }
   103→      // 변수 선언
   104→      if (line.startsWith('let ') || line.startsWith('const ')) {
   105→        output.push('  ' + line);
   106→        const m = line.match(/^(?:let|const)\s+(\w+)\s*=/);
   107→        if (m) output.push(`  _ctx['${m[1]}'] = ${m[1]};`);
   108→        return;
   109→      }
   110→      // 함수 선언
   111→      if (line.startsWith('function ')) {
   112→        output.push('  ' + line);
   113→        return;
   114→      }
   115→      // if/else
   116→      if (line.startsWith('if ') || line.startsWith('if(') ||
   117→          line.startsWith('} else') || line === '}' || line === '{') {
   118→        output.push('  ' + line);
   119→        return;
   120→      }
   121→      // 기타 (map/filter/reduce 결과 등)
   122→      output.push('  ' + line);
   123→    });
   124→
   125→    // DOM 준비 후 state 바인딩
   126→    output.push('  // DOM 이벤트 바인딩');
   127→    output.push('  document.addEventListener("DOMContentLoaded", function() {');
   128→    output.push('    var btns = document.querySelectorAll("button");');
   129→    output.push('    btns.forEach(function(btn) {');
   130→    output.push('      btn.addEventListener("click", function() {');
   131→    output.push('        if (typeof handleClick === "function") handleClick(this);');
   132→    output.push('        if (typeof increment  === "function") increment();');
   133→    output.push('        _updateDOM();');
   134→    output.push('      });');
   135→    output.push('    });');
   136→    output.push('    _updateDOM();');
   137→    output.push('  });');
   138→    output.push('  function _updateDOM() {');
   139→    output.push('    var displays = document.querySelectorAll("[data-bind]");');
   140→    output.push('    displays.forEach(function(el) {');
   141→    output.push('      var key = el.getAttribute("data-bind");');
   142→    output.push('      try { el.textContent = Object.prototype.hasOwnProperty.call(_ctx, key) ? _ctx[key] : ""; } catch(e) {}');
   143→    output.push('    });');
   144→    output.push('  }');
   145→    output.push('})();');
   146→
   147→    return output.join('\n');
   148→  }
   149→
   150→  // ─── HTML 컴파일 ────────────────────────────────────────────
   151→
   152→  _compileMarkup(markupBlock) {
   153→    if (!markupBlock.trim()) return '';
   154→
   155→    let html = markupBlock
   156→      // 중첩 markup { } 제거
   157→      .replace(/markup\s*\{/g, '')
   158→      .replace(/^\s*\}\s*$/gm, '')
   159→      // {{변수}} → <span data-bind="변수">변수</span>
   160→      .replace(/\{\{(\w+)\}\}/g, '<span data-bind="$1">$1</span>')
   161→      // 빈 줄 정리
   162→      .replace(/\n{3,}/g, '\n\n')
   163→      .trim();
   164→
   165→    return html;
   166→  }
   167→}
